import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import GroupBadge from 'flarum/common/components/GroupBadge';
import EditGroupModal from 'flarum/admin/components/EditGroupModal';
import Group from 'flarum/common/models/Group';
import Icon from 'flarum/common/components/Icon';

/**
 * This is just the group bar from the permissions page, extracted into its own component so it can be used again.
 */
export default class ExtractedGroupBar extends Component {
  view() {
    return m("div", {
      className: "PermissionsPage-groups"
    }, app.store.all('groups').filter(group => [Group.GUEST_ID, Group.MEMBER_ID].indexOf(group.id()) === -1).map(group => m("button", {
      className: "Button Group",
      onclick: () => app.modal.show(EditGroupModal, {
        group
      })
    }, m(GroupBadge, {
      group: group,
      className: "Group-icon",
      label: null
    }), m("span", {
      className: "Group-name"
    }, group.namePlural()))), m("button", {
      className: "Button Group Group--add",
      onclick: () => app.modal.show(EditGroupModal)
    }, m(Icon, {
      name: "fas fa-plus",
      className: "Group-icon"
    }), m("span", {
      className: "Group-name"
    }, app.translator.trans('core.admin.permissions.new_group_button'))));
  }
}
flarum.reg.add('ianm-twofactor', 'admin/components/ExtractedGroupBar', ExtractedGroupBar);